def count_ways_to_stair(k: int) -> int:
    if k == 0:
        return 2
    if k == 1:
        return 4
    jump = 0
    current_stair = 1
    ways = 0
    while current_stair <= k:
        if current_stair == k:
            ways += 1
        if current_stair + 2 ** jump <= k:
            ways += count_ways_to_stair(k - (current_stair + 2 ** jump))
        if current_stair > 1:
            ways += count_ways_to_stair(k - (current_stair - 1))
        jump += 1
        current_stair += 2 ** (jump - 1)
    return ways
